  {
    id: 'kpis',
    title: 'KPI',
    fields: ['kpis'],
    defaultOpen: true,
  },
  {
    id: 'geographic',
    title: 'Geographic',
    fields: ['zone', 'country', 'region'],
    defaultOpen: true,
  },
