      'audience_targeting_brands_comp',
    ],
    defaultOpen: true,
  },
  {
    id: 'scopes',
    title: 'Scopes',
    fields: ['distribution_scopes', 'scopes', 'sub_scopes'],
    defaultOpen: true,
  },
];

/**
 * Commercial Results drawer categories (Figma-aligned Other Filters section).
 */
export const COMMERCIAL_RESULTS_FILTER_CATEGORIES: FilterCategory[] = [
  {
    id: 'geographic',
    title: 'Geographic',
    fields: ['zone', 'country', 'region'],
    defaultOpen: true,
  },
  {
    id: 'timeframe',
    title: 'Time Frame',
    fields: ['periods'],
    defaultOpen: true,
  },
  {
    id: 'brands',
    title: 'Brands Hierarchy',
    fields: ['brands', 'sub_brands', 'sku'],
    defaultOpen: true,
  },
  {
    id: 'commercial_results_extras',
    title: 'Other Filters',
    fields: [
      'category',
      'non_alcoholic',
      'pack_type',
      'growth_levers',
      'beer_price_segment',
      'portfolios',
      'channel',
    ],
    defaultOpen: true,
  },
];

/**
 * WatchTower-specific tray filter categories.
 * Uses a separate Brand category for watch_tower_brand and groups
 * currency under Other Filters.
 */
export const WATCH_TOWER_FILTER_CATEGORIES: FilterCategory[] = [
  {
    id: 'kpis',
    title: 'KPI',
    fields: ['kpis'],
    defaultOpen: true,
  },
  {
    id: 'geographic',
    title: 'Geographic',
    fields: ['zone', 'country', 'region'],
    defaultOpen: true,
  },
  {
    id: 'watch_tower_brand',
    title: 'Brand',
    fields: ['watch_tower_brand'],
    defaultOpen: true,
  },
  {
    id: 'drivers',
    title: 'Drivers',
    fields: [
      'driver',
      'vehicle_level_1',
      'vehicle_level_2',
      'vehicle_level_3',
      'vehicle_level_4',
      'vehicle_level_5',
    ],
    defaultOpen: true,
  },
  {
    id: 'other_filters',
    title: 'Other Filters',
    fields: ['currency', 'channel'],
    defaultOpen: true,
  },
  {
    id: 'timeframe',
    title: 'Time Frame',
    fields: ['periods'],
    defaultOpen: true,
  },
];

// Helper function to get category by field key
export const getCategoryByField = (
  fieldKey: string,
  categories: FilterCategory[] = FILTER_CATEGORIES,
): FilterCategory | undefined => {
  return categories.find((category) =>
    category.fields.some(
      (field) => field.toLowerCase() === fieldKey.toLowerCase(),
    ),
  );
};

// Helper function to group fields by category
export const groupFieldsByCategory = (
  fieldKeys: string[],
  categories: FilterCategory[] = FILTER_CATEGORIES,
): Record<string, string[]> => {
  const grouped: Record<string, string[]> = {};

  categories.forEach((category) => {
    grouped[category.id] = [];
  });

  // Add 'uncategorized' for fields without a category
  grouped['uncategorized'] = [];

  fieldKeys.forEach((fieldKey) => {
    const category = getCategoryByField(fieldKey, categories);
    if (category) {
      grouped[category.id].push(fieldKey);
    } else {
      grouped['uncategorized'].push(fieldKey);
    }
  });

  // Remove empty categories
  Object.keys(grouped).forEach((key) => {
    if (grouped[key].length === 0) {
      delete grouped[key];
    }
  });

  return grouped;
};
